  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Bazedoxifene, the highest-transfer analogue (0.9876), has a direct human absolute oral bioavailability of about 6%, far below the 20% threshold, strongly supporting a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Raloxifene, with a transfer score of 0.9864, has human oral bioavailability of about 2% due to extensive first-pass metabolism, supporting low oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Tolperisone, with a transfer score of 0.9872, shows very low oral bioavailability in humans despite rapid absorption, consistent with a low-F outcome.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Avanafil, with a transfer score of 0.9852, has human bioavailability of only 8–10%, below the 20% threshold, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "CDP323, with a transfer score of 0.9836, showed an absolute bioavailability of 14% versus intravenous dosing in humans, still below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values well below 20% (approximately 2–14%), with no evidence supporting F ≥ 20%; therefore the query is predicted to have low oral bioavailability.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement is available for the query molecule itself.",
    "Query-specific metabolic stability, solubility, and transporter effects are not directly measured in the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

